	/** All subjects match both predicates exactly once. Only the supplied planning estimates are inaccurate. */
	private static final class CountingSource implements NativeLmdbQuerySource {
		final List<long[]> data = new ArrayList<>();
		int rootOpens, tailOpens, rootRows, tailRows, closed;

		CountingSource() {
			for (long s = 1L; s <= ROWS; s++) {
				data.add(new long[] { s, ROOT, 1_000L + s, 0L });
				data.add(new long[] { s, TAIL, 2_000L + s, 0L });
			}
			// A plausible128-row predicate sample remains below the exact total source count. These
			// irrelevant triples do not participate in either covered predicate range or the result bag.
			for (long i = 2L * ROWS; i < SOURCE_ENTRIES; i++) {
				data.add(new long[] { 10_000L + i, 3L, 20_000L + i, 0L });
			}
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public long idOf(Value value) {
			return value.stringValue().startsWith(NS)
					? Long.parseLong(value.stringValue().substring(NS.length()))
					: UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			return value(id);
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return coveringProfile(data.size());
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			return predicate == ROOT || predicate == TAIL ? OptionalDouble.of(1D) : OptionalDouble.empty();
		}

		@Override
		public OptionalDouble distinctFanOutKeys(long predicate, boolean bySubject) {
			return predicate == ROOT || predicate == TAIL ? OptionalDouble.of(ROWS) : OptionalDouble.empty();
		}

		@Override
		public OptionalLong adjacencyKeyDomainCardinality(long predicate, boolean bySubject) {
			return predicate == ROOT || predicate == TAIL ? OptionalLong.of(ROWS) : OptionalLong.empty();
		}

		private List<long[]> matches(long s, long p, long o, long c) {
			return data.stream()
					.filter(q -> (s == UNKNOWN_ID || s == q[0]) && (p == UNKNOWN_ID || p == q[1])
							&& (o == UNKNOWN_ID || o == q[2]) && (c == UNKNOWN_ID || c == q[3]))
					.toList();
		}

		@Override
		public RecordIterator statements(long s, long p, long o, long c) {
			assertThat(p).isIn(ROOT, TAIL);
			if (p == ROOT) {
				rootOpens++;
			} else {
				tailOpens++;
			}
			List<long[]> records = matches(s, p, o, c);
			return new RecordIterator() {
				int at;
				boolean done;

				@Override
				public long[] next() {
					if (at == records.size()) {
						return null;
					}
					if (p == ROOT) {
						rootRows++;
					} else {
						tailRows++;
					}
					return records.get(at++);
				}

				@Override
				public void close() {
					if (!done) {
						done = true;
						closed++;
					}
				}
			};
		}

		@Override
		public long count(long s, long p, long o, long c) {
			return matches(s, p, o, c).size();
		}

		@Override
		public boolean has(long s, long p, long o, long c) throws IOException {
			try (RecordIterator records = statements(s, p, o, c)) {
				return records.next() != null;
			}
		}

		@Override
		public double estimate(long s, long p, long o, long c) {
			return matches(s, p, o, c).size();
		}
	}
